import '../core/network/api_client.dart'; import '../models/cart.dart'; class CartRepository { CartRepository(this._api); final ApiClient _api; Future<CartModel> getCart() async=>CartModel.fromJson(Map<String,dynamic>.from(await _api.get('/api/cart'))); Future<CartModel> add(String productId,int quantity,{String? variantId}) async=>CartModel.fromJson(Map<String,dynamic>.from(await _api.post('/api/cart/items',body:{'productId':productId,'variantId':variantId,'quantity':quantity}))); Future<CartModel> update(String itemId,int quantity) async=>CartModel.fromJson(Map<String,dynamic>.from(await _api.put('/api/cart/items/$itemId',body:{'quantity':quantity}))); Future<CartModel> remove(String itemId) async=>CartModel.fromJson(Map<String,dynamic>.from(await _api.delete('/api/cart/items/$itemId'))); Future<void> clear() async=>_api.delete('/api/cart'); }